Here are the three files updated to strictly enforce the validation rules, apply defaults correctly, ignore client-sent IDs, and verify partial updates. The tests cover every requirement and will fail if the logic is reverted.

### `apps/server/src/adminLogic.ts`
```typescript
import { schema, FieldDef, SettingsFieldDef } from '../../shared/src/schema';

export function validateSettingsPatch(body: Record<string, unknown>): { valid: boolean; error?: string } {
  for (const [key, value] of Object.entries(body)) {
    const field = schema.settingsFields[key];
    if (!field) {
      return { valid: false, error: `Unknown setting: ${key}` };
    }
    if (field.wholeNumber) {
      if (typeof value !== 'number' || !Number.isInteger(value)) {
        return { valid: false, error: `${key} must be an integer` };
      }
    }
    if (key === 'GlossaryAutoLink' && typeof value !== 'boolean') {
      return { valid: false, error: 'GlossaryAutoLink must be true or false' };
    }
  }
  return { valid: true };
}

export function validateRequiredFields(
  body: Record<string, unknown>,
  fields: Record<string, FieldDef> | FieldDef[]
): { valid: boolean; error?: string } {
  const fieldList = Array.isArray(fields) ? fields : Object.values(fields);
  for (const f of fieldList) {
    if (f.required) {
      const val = body[f.name];
      if (
        val === undefined ||
        val === null ||
        (typeof val === 'string' && val.trim() === '')
      ) {
        return { valid: false, error: `${f.name} is required` };
      }
    }
  }
  return { valid: true };
}

export function applyDefaults(
  body: Record<string, unknown>,
  fields: Record<string, FieldDef> | FieldDef[]
): Record<string, unknown> {
  const fieldList = Array.isArray(fields) ? fields : Object.values(fields);
  const updated = { ...body };
  for (const f of fieldList) {
    if (f.default !== undefined && updated[f.name] === undefined) {
      updated[f.name] = f.default;
    }
  }
  return updated;
}
```

